-- ═══════════════════════════════════════════════════════════════════════════
-- FRETE JAMEF — carga de dados (94 tarifários + 5.419 faixas de CEP)
--
-- Gerado da planilha de contrato entregue pela Jamef. Roda DEPOIS de
-- 20260810000000_jamef_frete_schema.sql.
--
-- Tratamentos aplicados na geração, todos verificados nos dados de origem:
--   • 12 faixas de CEP duplicadas removidas (5.431 → 5.419). Eram linhas
--     idênticas, mesma sigla — ZERO conflito real de tarifário.
--   • 28 municípios traziam o IBGE como a STRING "None"; entram como NULL.
--     (O README da planilha afirma "100% dos municípios com IBGE" — não é o
--     caso. A busca por CEP não depende do IBGE, então não afeta a cotação.)
--   • FLORÍNEA/SP entra com sigla NULL (veio sem tarifário na planilha): a
--     cotação recusa com motivo próprio, em vez de fingir que não existe.
--   • AC, AM, RO e RR não estão na tabela — a Jamef não atende por ela.
-- ═══════════════════════════════════════════════════════════════════════════

