-- Conferência pós-carga (deve dar 94 e 5419).
do $$
declare t int; f int; s int;
begin
  select count(*) into t from public.jamef_tarifas;
  select count(*) into f from public.jamef_cep_faixas;
  select count(*) into s from public.jamef_cep_faixas where sigla is null;
  raise notice 'Jamef: % tarifários, % faixas de CEP, % faixa(s) sem tarifário', t, f, s;
end $$;
